"""Hand-written additions for drills the plan's notes don't cover.
ENRICH[title] = {'harder', 'easier', 'ask': [...], 's1', 's2', 'option', 'phase'}.
build_drills.py only adds a section a drill doesn't already have."""
FIELDS = {}
INTRO = {}


def E(harder=None, easier=None, ask=None, s1=None, s2=None, **kw):
    d = dict(harder=harder, easier=easier, ask=[ask] if isinstance(ask, str) else (ask or []), s1=s1, s2=s2)
    d.update(kw)
    return {k: v for k, v in d.items() if v}


